const DIET_SCHEMA: any = {
    type: Type.OBJECT,
    properties: {
        title: { type: Type.STRING, description: "e.g. 7-Day Anti-Diabetic Meal Plan" },
        overview: { type: Type.STRING, description: "Short summary of why this diet helps" },
