export const getDoctorAIResponse = async (history: ChatMessage[], scanHistory?: ScanHistoryItem[]): Promise<string> => {
  try {
    let contextData = "";
    if (scanHistory && scanHistory.length > 0) {
        const recentMedNames = scanHistory.slice(0, 5).map(item => item.medicineName).join(', ');
        contextData = `
        CONTEXT: The user's 5 most recent medicine scans are: [${recentMedNames}].
        Use this scan history to answer questions about past medicines or potential interactions.
        For example, if the user asks "can I take this with what I took yesterday?", refer to this list.
        `;
    }

    const MAX_HISTORY_MESSAGES = 10; // Reduced history to prevent overload
    const relevantHistory = history.filter(msg => msg.id !== 'welcome' && msg.content.trim() !== '');
    const truncatedHistory = relevantHistory.slice(-MAX_HISTORY_MESSAGES);

    const contents = truncatedHistory.map(msg => ({
      role: msg.role === 'user' ? 'user' : 'model',
      parts: [{ text: msg.content }]
    }));

    if (contents.length === 0) {
        return "How can I help you today?";
    }

    const systemInstruction = `You are 'MediIQ Doctor AI', a professional and empathetic medical assistant. 
    ${contextData}
    Help users understand symptoms, health conditions, and wellness. 
    ALWAYS include a disclaimer that you are an AI and not a real doctor. 
    If symptoms sound severe, strongly advise visiting an Emergency Room immediately. 
    Keep responses concise and structured with bullet points where appropriate.`;

    // Using a single, reliable model. Removed complex retry logic for simplicity and stability.
    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview", // Sticking to the more reliable and faster model
            contents: contents,
            config: { systemInstruction }
        });
        return response.text || "I apologize, I'm having trouble processing that right now. Could you rephrase?";
    } catch (error: any) {
        const errorMsg = JSON.stringify(error);
        console.error("Doctor AI Critical Error:", errorMsg); 
        if (errorMsg.includes("429") || errorMsg.includes("quota")) {
            return "Server usage limit reached. Please come back tomorrow.";
        }
        // A more helpful error message for users
        return "I am currently unavailable due to a technical issue. Please try again in a moment. If the problem continues, clearing the chat might help resolve it.";
    }
  } catch (error) {
    console.error("Doctor AI Top-Level Error:", error);
    return "I'm currently unable to assist due to a connection issue. If this is an emergency, please call local medical services immediately.";
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import Scanner from './components/Scanner.tsx';
import MedicineResult from './components/MedicineResult.tsx';
import Reminders from './components/Reminders.tsx';
import History from './components/History.tsx';
import DoctorAI from './components/DoctorAI.tsx';
import PremiumModal from './components/PremiumModal.tsx';
import Profile from './components/Profile.tsx';
import LegalAndHelp from './components/LegalAndHelp.tsx';
import AlarmRingingModal from './components/AlarmRingingModal.tsx';
import IntroFlow from './components/IntroFlow.tsx';
import LoginScreen from './components/LoginScreen.tsx';
import ExpiryCabinet from './components/ExpiryCabinet.tsx';
import EmergencyWallpaper from './components/EmergencyWallpaper.tsx';
import DermaScanner from './components/DermaScanner.tsx';
import { MedicineData, AppView, Reminder, PatientProfile, ScanHistoryItem, FamilyMember, User, CabinetItem, ChatMessage } from './types.ts';
import { getHealthTip } from './services/geminiService.ts';
import { subscribeToAuthChanges, loginWithGoogle, logout, handleRedirectResult } from './services/authService.ts';

const App: React.FC = () => {
  // -- Auth State --
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isGuest, setIsGuest] = useState<boolean>(() => localStorage.getItem('mediScan_is_guest') === 'true');
  const [authChecked, setAuthChecked] = useState(false);
  const [showIntro, setShowIntro] = useState<boolean>(true);

  // -- Data State (Initialized Empty, Loaded via Effect) --
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [scanHistory, setScanHistory] = useState<ScanHistoryItem[]>([]);
  const [familyMembers, setFamilyMembers] = useState<FamilyMember[]>([]);
  const [cabinetItems, setCabinetItems] = useState<CabinetItem[]>([]);
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isPremium, setIsPremium] = useState<boolean>(false);

  // -- UI State --
  const [currentView, setCurrentView] = useState<AppView>(AppView.HOME);
  const [scannedData, setScannedData] = useState<MedicineData | null>(null);
  const [patientProfile, setPatientProfile] = useState<PatientProfile | undefined>(undefined);
  const [showPremiumModal, setShowPremiumModal] = useState(false);
  const [healthTip, setHealthTip] = useState<string>("");
  const [isPreviouslyScanned, setIsPreviouslyScanned] = useState(false);
  const [overdoseWarning, setOverdoseWarning] = useState(false);
  const [activeAlarm, setActiveAlarm] = useState<Reminder | null>(null);
  const [notificationPermission, setNotificationPermission] = useState<NotificationPermission>(() => Notification.permission);
  const [isLoadingData, setIsLoadingData] = useState(true);

  // Helper: Generate Storage Key based on User
  const getStorageKey = useCallback((baseKey: string) => {
    if (currentUser) {
      return `mediScan_${currentUser.uid}_${baseKey}`;
    }
    // Guest keys modified to prevent overlap with legacy un-prefixed keys
    if (isGuest) {
      return `mediScan_guest_${baseKey}`;
    }
    return `mediScan_${baseKey}`; // Fallback for legacy
  }, [currentUser, isGuest]);

  // -- Initialization & Auth --
  useEffect(() => {
    const introSeen = localStorage.getItem('mediScan_intro_seen');
    if (introSeen) setShowIntro(false);

    handleRedirectResult().catch((error) => console.error("Redirect Error:", error));

    const unsubscribe = subscribeToAuthChanges((user) => {
      setCurrentUser(user);
      setAuthChecked(true);
      if (user) {
          setIsGuest(false);
          localStorage.removeItem('mediScan_is_guest');
      }
    });

    if (!localStorage.getItem('mediScan_deviceId')) {
        localStorage.setItem('mediScan_deviceId', crypto.randomUUID());
    }
    getHealthTip().then(setHealthTip).catch(() => setHealthTip("Always verify medicine with a doctor."));

    return () => unsubscribe();
  }, []);

  // -- Load Data when User Changes --
  useEffect(() => {
    if (!authChecked) return;
    if (!currentUser && !isGuest) return;

    setIsLoadingData(true);

    const loadData = (key: string, setter: (data: any) => void, defaultValue: any) => {
      try {
        const saved = localStorage.getItem(getStorageKey(key));
        setter(saved ? JSON.parse(saved) : defaultValue);
      } catch { setter(defaultValue); }
    };

    loadData('reminders', setReminders, []);
    loadData('history', setScanHistory, []);
    loadData('cabinet', setCabinetItems, []);

    const initialChat: ChatMessage[] = [{ id: 'welcome', role: 'assistant', content: 'Hello! I am your MediIQ Doctor AI. I can access your scan history to give you better advice. How can I help you today?', timestamp: Date.now() }];
    loadData('chat_history', setChatHistory, initialChat);

    try {
        const savedFamily = localStorage.getItem(getStorageKey('family'));
        if (savedFamily) {
            setFamilyMembers(JSON.parse(savedFamily));
        } else {
            const defaultMe: FamilyMember = {
                id: 'me', name: currentUser?.displayName || 'Me', ageGroup: 'adult', gender: 'male', 
                isPregnant: false, isBreastfeeding: false, language: 'english', 
                avatar: currentUser?.photoURL ? '📸' : '🧑‍💻'
            };
            setFamilyMembers([defaultMe]);
        }
    } catch { setFamilyMembers([]); }

    try {
        setIsPremium(localStorage.getItem(getStorageKey('premium')) === 'true');
    } catch { setIsPremium(false); }

    setIsLoadingData(false);

  }, [currentUser, isGuest, authChecked, getStorageKey]);

  // -- Save Data Effects (Triggered on State Change) --
  const useSaveData = (key: string, data: any) => {
    useEffect(() => {
      if (isLoadingData) return;
      localStorage.setItem(getStorageKey(key), JSON.stringify(data));
    }, [data, getStorageKey, isLoadingData]);
  };

  useSaveData('reminders', reminders);
  useSaveData('history', scanHistory);
  useSaveData('family', familyMembers);
  useSaveData('cabinet', cabinetItems);
  useSaveData('chat_history', chatHistory);
  useSaveData('premium', isPremium);


  // -- Alarm Checker & Expiry Notification --
  useEffect(() => {
    const interval = setInterval(() => {
        const now = new Date();
        const currentTime = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;

        const triggered = reminders.find(r => r.active && r.time === currentTime && (!r.snoozedUntil || Date.now() >= r.snoozedUntil));
        if (triggered && !activeAlarm) {
            setActiveAlarm(triggered);
        }
    }, 10000); 

    if (cabinetItems.length > 0 && notificationPermission === 'granted') {
        const now = new Date();
        cabinetItems.forEach(item => {
            const expiry = new Date(item.expiryDate);
            const diffTime = expiry.getTime() - now.getTime();
            const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

            if (diffDays <= 7 && diffDays >= -1) {
                 const noteTitle = diffDays < 0 ? `⚠️ EXPIRED: ${item.medicineName}` : `⚠️ Expiry Alert: ${item.medicineName}`;
                 const noteBody = diffDays < 0 ? "Throw it away! This medicine has become poison." : `Expires in ${diffDays} days. Plan to dispose of it soon.`;

                 const key = `expiry_alert_${item.id}_${now.toDateString()}`;
                 if (!sessionStorage.getItem(key)) {
                    new Notification(noteTitle, { body: noteBody, icon: '/favicon.png' });
                    sessionStorage.setItem(key, 'sent');
                 }
            }
        });
    }

    return () => clearInterval(interval);
  }, [reminders, activeAlarm, cabinetItems, notificationPermission]);

  // -- Handlers --

  const requestNotificationPermission = async () => {
    if (Notification.permission === 'default') {
      const permission = await Notification.requestPermission();
      setNotificationPermission(permission);
    }
  };

  const handleUpgrade = async (txnId?: string) => {
    setIsPremium(true);
    if (txnId) localStorage.setItem(getStorageKey('txnId'), txnId);
    setShowPremiumModal(false);
    setCurrentView(AppView.PROFILE);
  };

  const handleLogin = async () => {
    try { await loginWithGoogle(); } catch (error) { alert("Login initiation failed. Please try again."); }
  };

  const handleGuestContinue = () => {
      setIsGuest(true);
      localStorage.setItem('mediScan_is_guest', 'true');
  };

  const handleLogout = async () => {
    try {
        await logout();
        setIsGuest(false);
        setScannedData(null);
        setCurrentView(AppView.HOME);
        localStorage.removeItem('mediScan_is_guest');
    } catch (error) { console.error("Logout failed", error); }
  };

  const addReminder = (r: Reminder) => setReminders(prev => [...prev, r]);
  const deleteReminder = (id: string) => setReminders(prev => prev.filter(r => r.id !== id));
  const toggleReminder = (id: string) => setReminders(prev => prev.map(r => r.id === id ? { ...r, active: !r.active } : r));
  const updateReminder = (updated: Reminder) => setReminders(prev => prev.map(r => r.id === updated.id ? updated : r));

  const addCabinetItem = (item: CabinetItem) => setCabinetItems(prev => [...prev, item]);
  const deleteCabinetItem = (id: string) => setCabinetItems(prev => prev.filter(i => i.id !== id));
  const clearExpiredCabinet = () => {
      const now = new Date();
      setCabinetItems(prev => prev.filter(i => new Date(i.expiryDate) >= now));
  };

  const clearChatHistory = () => {
      const welcome: ChatMessage = { id: 'welcome', role: 'assistant', content: 'Hello! I am your MediIQ Doctor AI. I can access your scan history to give you better advice. How can I help you today?', timestamp: Date.now() };
      setChatHistory([welcome]);
  };

  const handleScanComplete = (data: MedicineData, profile: PatientProfile) => {
    const now = Date.now();
    const fourHours = 4 * 60 * 60 * 1000;
    const recentScan = scanHistory.find(item => item.medicineName.toLowerCase().trim() === data.name.toLowerCase().trim() && (now - item.timestamp) < fourHours);
    setIsPreviouslyScanned(scanHistory.some(item => item.medicineName.toLowerCase().trim() === data.name.toLowerCase().trim()));
    setOverdoseWarning(!!recentScan);
    setScanHistory(prev => [{ id: crypto.randomUUID(), timestamp: now, medicineName: data.name, data }, ...prev].slice(0, 20));
    setScannedData(data);
    setPatientProfile(profile);
  };

  const handleIntroComplete = () => {
    localStorage.setItem('mediScan_intro_seen', 'true');
    setShowIntro(false);
  };

  // -- Render Flow --

  if (showIntro) {
    return <IntroFlow onComplete={handleIntroComplete} />;
  }

  if (authChecked && !currentUser && !isGuest) {
      return <LoginScreen onLogin={handleLogin} onGuest={handleGuestContinue} />;
  }

  const renderContent = () => {
    if (scannedData) {
      return (
        <MedicineResult 
          data={scannedData} 
          profile={patientProfile} 
          isPremium={isPremium} 
          isPreviouslyScanned={isPreviouslyScanned} 
          overdoseWarning={overdoseWarning} 
          onOpenPremium={() => setShowPremiumModal(true)} 
          onClose={() => setScannedData(null)}
          onAddReminder={(rem) => {
            addReminder(rem);
            setCurrentView(AppView.REMINDERS);
            setScannedData(null);
