                </div>

                {!isPremium && (
                    <div onClick={() => setShowPremiumModal(true)} className="mt-6 bg-slate-900 text-white p-7 rounded-[3rem] shadow-2xl shadow-slate-900/20 flex justify-between items-center cursor-pointer transform transition-all hover:translate-y-[-2px] active:scale-95 group relative overflow-hidden border border-slate-800">
                        <div className="absolute inset-0 bg-gradient-to-br from-slate-800 to-slate-900 z-0"></div>
                        <div className="absolute -top-12 -right-12 w-48 h-48 bg-white opacity-[0.05] rounded-full blur-3xl group-hover:opacity-10 transition-opacity"></div>
                        <div className="relative z-10 text-left">
                            <h3 className="font-extrabold text-xl flex items-center tracking-tight">Expert Insights <span className="ml-2">💎</span></h3>
                            <p className="text-[10px] text-slate-500 mt-1 font-black uppercase tracking-widest opacity-80">Unlock Detailed Safety Reports</p>
                        </div>
                        <div className="relative z-10 bg-white text-slate-900 px-6 py-3 rounded-2xl font-black text-xs shadow-xl tracking-widest uppercase">₹99</div>
                    </div>
                )}
            </div>
          </div>
        );
      case AppView.REMINDERS:
        return <div className="pb-24 bg-slate-50 min-h-screen"><Reminders reminders={reminders} addReminder={addReminder} updateReminder={updateReminder} deleteReminder={deleteReminder} toggleReminder={toggleReminder} notificationPermission={notificationPermission} onRequestNotificationPermission={requestNotificationPermission} /></div>;
      case AppView.CABINET:
          return <ExpiryCabinet items={cabinetItems} onDeleteItem={deleteCabinetItem} onClearExpired={clearExpiredCabinet} />;
      case AppView.EMERGENCY:
          return <EmergencyWallpaper onBack={() => setCurrentView(AppView.HOME)} userDisplayName={currentUser?.displayName || undefined} />;
      case AppView.DERMA:
          return <DermaScanner onBack={() => setCurrentView(AppView.HOME)} />;
      case AppView.HISTORY:
        return <div className="pb-24 bg-slate-50 min-h-screen"><History history={scanHistory} onSelectItem={(data) => { setScannedData(data); setOverdoseWarning(false); setIsPreviouslyScanned(true); }} onClearHistory={() => setScanHistory([])} /></div>;
      case AppView.DOCTOR_AI:
        return <DoctorAI isPremium={isPremium} onOpenPremium={() => setShowPremiumModal(true)} userId={currentUser?.uid || 'guest'} messages={chatHistory} setMessages={setChatHistory} onClearChat={clearChatHistory} scanHistory={scanHistory} />;
      case AppView.INFO:
          return <div className="pb-24 bg-slate-50 min-h-screen"><LegalAndHelp /></div>;
      case AppView.PROFILE:
          return (
            <div className="pb-24 bg-slate-50 min-h-screen">
              <Profile 
                isPremium={isPremium} 
                familyMembers={familyMembers} 
                setFamilyMembers={setFamilyMembers} 
                user={currentUser}
                onLogin={handleLogin}
                onLogout={handleLogout}
              />
            </div>
          );
      default:
        return <div className="p-10 text-center">View not found</div>;
    }
  };

  return (
    <div className="max-w-md mx-auto min-h-screen relative shadow-2xl overflow-hidden font-sans text-slate-800 bg-slate-50">
      <main className="min-h-screen relative z-10 overflow-y-auto hide-scrollbar bg-slate-50">
        {renderContent()}
      </main>

      {activeAlarm && (
          <AlarmRingingModal 
            reminder={activeAlarm} 
            onTake={() => { setActiveAlarm(null); toggleReminder(activeAlarm.id); }}
            onSnooze={(mins) => { setActiveAlarm(null); }}
            onSkip={() => { setActiveAlarm(null); }}
            notificationPermission={notificationPermission}
          />
      )}

      {showPremiumModal && (
        <PremiumModal 
          isOpen={showPremiumModal} 
          onClose={() => setShowPremiumModal(false)} 
          onUpgrade={handleUpgrade} 
        />
      )}

      {!scannedData && !activeAlarm && (
        <div className="fixed bottom-0 left-0 right-0 max-w-md mx-auto z-[100] bg-white border-t border-slate-100 shadow-[0_-5px_20px_rgba(0,0,0,0.05)] pb-safe">
            <nav className="flex justify-around items-center px-2 py-3">
                {[
                    { view: AppView.HOME, icon: "M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z M15 13a3 3 0 11-6 0 3 3 0 016 0z", label: "Scan" },
                    { view: AppView.HISTORY, icon: "M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z", label: "History" },
                    { view: AppView.REMINDERS, icon: "M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9", label: "Alarms" },
                    { view: AppView.DOCTOR_AI, icon: "M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z", label: "Doctor" },
                    { view: AppView.PROFILE, icon: "M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14", label: "Profile" }
                ].map((item) => {
                    const isActive = currentView === item.view || (item.view === AppView.HOME && (currentView === AppView.SCANNER || currentView === AppView.DERMA));
                    return (
                        <button key={item.label} onClick={() => setCurrentView(item.view)} className={`flex flex-col items-center justify-center w-14 py-1 rounded-xl transition-all duration-300 ${isActive ? 'text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}>
                            <div className={`mb-1 transition-all duration-300 ${isActive ? 'bg-slate-900 text-white p-2.5 rounded-2xl shadow-lg' : ''}`}>
                                <svg className={`w-6 h-6 ${isActive ? 'stroke-2' : 'stroke-[1.5]'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" d={item.icon} />
                                </svg>
                            </div>
                            {!isActive && <span className="text-[9px] font-bold tracking-wide">{item.label}</span>}
                        </button>
                    );
                })}
            </nav>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { ChatMessage, ScanHistoryItem } from '../types.ts';
import { getDoctorAIResponse } from '../services/geminiService.ts';

interface DoctorAIProps {
  isPremium: boolean;
  onOpenPremium: () => void;
  userId: string;
  messages: ChatMessage[];
  setMessages: (messages: ChatMessage[]) => void;
  onClearChat: () => void;
  scanHistory: ScanHistoryItem[];
}

// Type definition for Web Speech API
declare global {
  interface Window {
    webkitSpeechRecognition: any;
    SpeechRecognition: any;
  }
}

const DoctorAI: React.FC<DoctorAIProps> = ({ isPremium, onOpenPremium, userId, messages, setMessages, onClearChat, scanHistory }) => {
  const getUsageKey = () => userId === 'guest' ? 'mediIQ_daily_chat_usage' : `mediIQ_${userId}_daily_chat_usage`;

  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const recognitionRef = useRef<any>(null);

  const [usage, setUsage] = useState(() => {
    const today = new Date().toISOString().split('T')[0];
    const saved = localStorage.getItem(getUsageKey());
    if (saved) {
      const parsed = JSON.parse(saved);
      if (parsed.date === today) return parsed.count;
    }
    return 0;
  });

  const scrollRef = useRef<HTMLDivElement>(null);
  const MAX_FREE_MESSAGES = 10;
  const isLimitReached = !isPremium && usage >= MAX_FREE_MESSAGES;

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  useEffect(() => {
    const today = new Date().toISOString().split('T')[0];
    localStorage.setItem(getUsageKey(), JSON.stringify({ date: today, count: usage }));
  }, [usage, userId]);

  // Cleanup speech recognition on unmount
  useEffect(() => {
    return () => {
      if (recognitionRef.current) {
        recognitionRef.current.stop();
      }
    };
  }, []);

  const handleVoiceInput = () => {
    if (isListening) {
      recognitionRef.current?.stop();
      return;
    }

    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Voice input is not supported in this browser. Please use Chrome or Safari.");
      return;
    }

    const recognition = new SpeechRecognition();
    recognitionRef.current = recognition;
    recognition.lang = 'en-US'; 
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;

    recognition.onstart = () => setIsListening(true);

    recognition.onend = () => {
      setIsListening(false);
      recognitionRef.current = null;
    };

    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      if (transcript) {
        setInput(prev => {
          const trimmed = prev.trim();
          return trimmed ? `${trimmed} ${transcript}` : transcript;
        });
      }
    };

    recognition.onerror = (event: any) => {
      console.error("Speech recognition error", event.error);
      setIsListening(false);
    };

    try {
      recognition.start();
    } catch (e) {
      console.error("Failed to start recognition", e);
    }
  };

  const handleSend = async (text: string) => {
    if (!text.trim() || isLoading || isLimitReached) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user' as const,
      content: text,
      timestamp: Date.now()
    };

    const newMessages = [...messages, userMsg];
    setMessages(newMessages);
    setInput('');
    setIsLoading(true);
    if (!isPremium) setUsage(prev => prev + 1);

    try {
      const responseText = await getDoctorAIResponse(newMessages, scanHistory);
      const assistantMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant' as const,
        content: responseText,
        timestamp: Date.now()
      };
      setMessages([...newMessages, assistantMsg]);
    } catch (error) {
      console.error("Chat error", error);
      const errorMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant' as const,
        content: "Sorry, I encountered an error. Please try again.",
        timestamp: Date.now()
      };
      setMessages([...newMessages, errorMsg]);
    } finally {
      setIsLoading(false);
    }
  };

  const quickPrompts = [
    "Check my history for conflicts",
    "Should I take Advil for headache?",
    "Healthy breakfast tips",
    "How to treat a burn?"
  ];

  return (
    <div className="flex flex-col h-screen max-w-lg mx-auto bg-slate-50 relative overflow-hidden">
      <header className="p-6 pt-10 bg-white border-b border-slate-100 shrink-0 relative z-[60] shadow-sm">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3">
             <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center text-2xl shadow-lg shadow-indigo-100 relative">
               👨‍⚕️
               {scanHistory.length > 0 && (
                   <span className="absolute -bottom-1 -right-1 w-4 h-4 bg-teal-500 rounded-full border-2 border-white animate-pulse" title="Connected to Scan History"></span>
               )}
             </div>
             <div>
               <h2 className="text-xl font-black text-slate-900 tracking-tight leading-none mb-1">Doctor AI</h2>
               <div className="flex items-center space-x-2">
                 {scanHistory.length > 0 ? (
                     <span className="text-[9px] font-bold text-teal-600 bg-teal-50 px-2 py-0.5 rounded-md uppercase tracking-widest">History Connected</span>
                 ) : (
                    <span className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">No History</span>
                 )}
               </div>

               {!isPremium && (
                 <div className="flex items-center space-x-2 mt-1">
                    <div className="w-16 h-1 bg-slate-100 rounded-full overflow-hidden">
                        <div className="h-full bg-indigo-500" style={{ width: `${(usage/MAX_FREE_MESSAGES)*100}%` }}></div>
                    </div>
                    <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest">{MAX_FREE_MESSAGES - usage} Left</span>
                 </div>
               )}
               {isPremium && (
                 <div className="flex items-center mt-1">
                    <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse mr-1"></div>
                    <span className="text-[8px] font-bold text-emerald-500 uppercase tracking-widest">Premium Active</span>
                 </div>
               )}
             </div>
          </div>
          {messages.length > 1 && (
            <button 
              onClick={onClearChat}
              className="p-3 bg-slate-50 text-slate-400 rounded-xl hover:text-rose-500 hover:bg-rose-50 transition-all active:scale-90"
              title="Clear Chat"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
            </button>
          )}
        </div>
      </header>

      <div className="flex-1 overflow-y-auto p-6 space-y-6 pb-64 no-scrollbar bg-slate-50">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-slide-up`}>
            <div className={`max-w-[85%] p-5 rounded-[2rem] shadow-sm text-sm leading-relaxed ${
              msg.role === 'user' 
                ? 'bg-indigo-600 text-white rounded-br-none shadow-indigo-100' 
                : 'bg-white text-slate-800 rounded-bl-none border border-slate-100'
            }`}>
              {msg.content.split('\n').map((line, i) => (
                <p key={i} className={i > 0 ? 'mt-2' : ''}>{line}</p>
              ))}
              <div className="flex items-center justify-between mt-3">
                  <p className={`text-[8px] font-bold uppercase tracking-widest ${msg.role === 'user' ? 'text-indigo-200' : 'text-slate-300'}`}>
                    {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </p>
                  {msg.role === 'assistant' && <span className="text-[10px] opacity-20">🏥</span>}
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start animate-fade-in">
            <div className="bg-white p-5 rounded-[2rem] rounded-bl-none border border-slate-100 shadow-sm flex items-center space-x-1.5">
               <div className="w-2 h-2 bg-indigo-200 rounded-full animate-bounce"></div>
               <div className="w-2 h-2 bg-indigo-300 rounded-full animate-bounce delay-75"></div>
               <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce delay-150"></div>
            </div>
          </div>
        )}
        <div ref={scrollRef} />
      </div>

      <div className="fixed bottom-0 left-0 right-0 max-w-md mx-auto z-[70] bg-slate-50 border-t border-slate-100 px-6 pt-6 pb-28">
        {isLimitReached ? (
            <div className="bg-white rounded-[2.5rem] p-6 shadow-xl border-2 border-indigo-100 text-center animate-slide-up">
                <div className="text-2xl mb-2">🛑</div>
                <h3 className="text-sm font-black text-slate-900 uppercase tracking-tight">Daily Limit Reached</h3>
                <p className="text-[10px] text-slate-500 font-bold mb-4 uppercase tracking-widest">Upgrade to Premium for unlimited AI Consultation</p>
                <button 
                    onClick={onOpenPremium}
                    className="w-full bg-indigo-600 text-white py-4 rounded-2xl font-black text-xs uppercase tracking-widest shadow-lg shadow-indigo-200 active:scale-95 transition-all"
                >
                    Unlock Unlimited Forever 👑
                </button>
            </div>
        ) : (
            <>
                {messages.length < 3 && !isLoading && (
                <div className="flex overflow-x-auto no-scrollbar space-x-2 mb-4">
                    {quickPrompts.map(p => (
                    <button key={p} onClick={() => handleSend(p)} className="shrink-0 bg-white border border-slate-200 text-slate-500 px-5 py-2.5 rounded-2xl text-[9px] font-black uppercase tracking-widest hover:bg-indigo-50 hover:text-indigo-600 hover:border-indigo-100 transition-all active:scale-95 shadow-sm">
                        {p}
                    </button>
                    ))}
                </div>
                )}

                <div className="bg-white rounded-[2.5rem] p-2 shadow-[0_-10px_40px_rgba(15,23,42,0.05)] border border-slate-100 flex items-center">
                    <input 
                        type="text" 
                        value={input}
                        onChange={(e) => setInput(e.target.value)}
                        onKeyPress={(e) => e.key === 'Enter' && handleSend(input)}
                        placeholder="Describe your symptoms..."
                        className="flex-1 bg-transparent border-none focus:ring-0 text-slate-800 text-sm font-bold px-6 placeholder-slate-300"
                    />

                    <button
                      onClick={handleVoiceInput}
                      className={`w-10 h-10 rounded-2xl mr-2 flex items-center justify-center transition-all ${isListening ? 'bg-rose-500 text-white animate-pulse' : 'text-slate-400 hover:text-indigo-500 bg-slate-50'}`}
                      title={isListening ? "Stop listening" : "Speak"}
                    >
                      {isListening ? (
                        <div className="w-3 h-3 bg-white rounded-sm animate-bounce"></div>
                      ) : (
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                      )}
                    </button>

                    <button 
                        onClick={() => handleSend(input)}
                        disabled={!input.trim() || isLoading}
                        className={`w-14 h-14 rounded-3xl flex items-center justify-center transition-all ${input.trim() ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-200' : 'bg-slate-100 text-slate-300'}`}
                    >
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 10l7-7m0 0l7 7m-7-7v18" /></svg>
                    </button>
                </div>
            </>
        )}
        <p className="text-center text-[7px] font-black text-slate-300 uppercase tracking-[0.3em] mt-6 leading-relaxed px-4">AI Doctor can make mistakes. For serious conditions, see a human doctor immediately.</p>
      </div>
    </div>
  );
};

export default DoctorAI;

export type AgeGroup = 'child' | 'adult' | 'senior';
export type Gender = 'male' | 'female';
export type Language = 'english' | 'hindi' | 'hinglish';
export type VoiceGender = 'male' | 'female';

export interface FamilyMember {
  id: string;
  name: string;
  ageGroup: AgeGroup;
  gender: Gender;
  isPregnant: boolean;
  isBreastfeeding: boolean;
  language: Language;
  avatar: string;
}

export interface User {
  uid: string;
  email: string | null;
  displayName?: string | null;
  photoURL?: string | null;
  isGuest: boolean;
  joinedAt: number;
}

export interface PatientProfile {
  ageGroup: AgeGroup;
  gender: Gender;
  isPregnant: boolean;
  isBreastfeeding: boolean;
  language: Language;
}

export type RiskScore = 'Low' | 'Medium' | 'High';

export interface InteractionRisk {
  severity: 'Safe' | 'Warning' | 'Dangerous';
  summary: string;
  advice: string;
}

export interface MedicineData {
  name: string; 
  medicationsFound: string[]; 
  description: string;
  simpleExplanation: string;
  childFriendlyExplanation: string;
  uses: string[];
  dosage: string;
  sideEffects: string[];
  warnings: string;
  keyWarning: string;
  riskScore: RiskScore;
  riskReason: string;
  whoShouldAvoid: string[];
  foodGuidance: string; 
  alternatives: string[];
  interactionAnalysis?: InteractionRisk;
  effectTimeline: {
      onset: string;
      peak: string;
      duration: string;
  };
  lifestyleWarnings: {
      alcohol: boolean;
      driving: boolean;
      sleep: boolean;
  };
  safetyRating: number;
  commonQuestions: {
      question: string;
      answer: string;
  }[];
  criticalWarning?: string; 
  pregnancyWarning?: string;
  breastfeedingWarning?: string;
  ageAdvice?: string;
  expiryDate?: string; // YYYY-MM-DD format if found
}

export interface DermaData {
  conditionName: string;
  confidence: string; // High, Medium, Low
  severity: 'Mild' | 'Moderate' | 'Severe';
  description: string;
  symptomsObserved: string[];
  possibleCauses: string[];
  homeRemedies: string[];
  otcSuggestions: string[]; // Over the counter creams/meds
  whenToSeeDoctor: string;
  isContagious: boolean;
  disclaimer: string;
}

export interface DayPlan {
    day: string;
    morning: string; // Early morning drink/snack
    breakfast: string;
    lunch: string;
    snack: string; // Evening
    dinner: string;
    tip: string;
}

export interface DietPlan {
    title: string;
    overview: string;
    avoidList: string[];
    includeList: string[];
    days: DayPlan[];
}

export interface ScanHistoryItem {
  id: string;
  timestamp: number;
  medicineName: string;
  data: MedicineData;
}

export interface CabinetItem {
  id: string;
  medicineName: string;
  expiryDate: string; // YYYY-MM-DD
  addedAt: number;
  notes?: string;
  isExpired: boolean;
}

export type FoodContext = 'before_food' | 'after_food' | 'empty_stomach' | 'any';
export type RepeatType = 'daily' | 'alternate' | 'custom';
export type SoundType = 'default' | 'soft' | 'loud' | 'voice' | 'zen' | 'emergency' | 'musical' | 'ringtone' | 'custom';
export type VoiceTone = 'normal' | 'strict' | 'friendly' | 'hindi';

export interface Reminder {
  id: string;
  medicineName: string;
  dose: string;
  time: string; 
  foodContext: FoodContext;
  repeat: RepeatType;
  customDays: number[]; 
  soundType: SoundType;
  customSoundData?: string; 
  voiceTone?: VoiceTone;
  voiceGender?: VoiceGender;
  active: boolean;
  snoozedUntil: number | null;
  createdAt: number;
}

export enum AppView {
  HOME = 'HOME',
  SCANNER = 'SCANNER',
  REMINDERS = 'REMINDERS',
  HISTORY = 'HISTORY',
  DOCTOR_AI = 'DOCTOR_AI',
  PROFILE = 'PROFILE',
  INFO = 'INFO',
  CABINET = 'CABINET',
  EMERGENCY = 'EMERGENCY',
  DERMA = 'DERMA'
}

export interface AnalysisState {
  loading: boolean;
  data: MedicineData | null;
  error: string | null;
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: number;
}

