  ]
};

const DERMA_SCHEMA: any = {
  type: Type.OBJECT,
  properties: {
    conditionName: { type: Type.STRING },
    confidence: { type: Type.STRING, enum: ["High", "Medium", "Low"] },
    severity: { type: Type.STRING, enum: ["Mild", "Moderate", "Severe"] },
