    isContagious: { type: Type.BOOLEAN },
    disclaimer: { type: Type.STRING }
  },
  required: ["conditionName", "severity", "description", "symptomsObserved", "homeRemedies", "otcSuggestions", "whenToSeeDoctor", "disclaimer"]
};

