`;

// --- GENERIC FALLBACK HANDLER ---
const generateContentWithFallback = async (params: any, isVision: boolean = false): Promise<string> => {
    // Models priority list
    const models = ["gemini-1.5-flash", "gemini-1.5-pro"]; 
    if (!isVision) {
        models.push("gemini-pro"); // Legacy text model
    }

    let lastError = null;

    for (const modelName of models) {
        try {
            console.log(`MediIQ: Attempting ${modelName}`);
            const model = genAI.getGenerativeModel({ 
                model: modelName,
                safetySettings: SAFETY_SETTINGS,
                generationConfig: { responseMimeType: "application/json" }
            });

            // Standardize contents for @google/generative-ai
            // It expects [ string, part, part ] or just string
            let finalContent: any = [];

            if (params.contents && Array.isArray(params.contents)) {
                // Chat format (Doctor AI) - handling specially below
            } else if (params.contents && params.contents.parts) {
                // Vision format
                finalContent = params.contents.parts;
            } else {
                // String prompt
                finalContent = [params.contents];
            }

            const result = await model.generateContent(finalContent);
            const response = await result.response;
            const text = response.text();

            if (!text) throw new Error("Empty response from AI");
            return text;

        } catch (error: any) {
            console.warn(`MediIQ: Model ${modelName} failed:`, error.message);
            lastError = error;
            // Continue to next model
        }
    }
    throw lastError;
};

