const CACHE_NAME = 'mediiq-offline-v1';
const ASSETS_TO_CACHE = [
  './',
  './index.html',
  'https://cdn.tailwindcss.com',
  'https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap'
];

// Install Event - Cache Files
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => {
        return cache.addAll(ASSETS_TO_CACHE);
      })
      .then(() => self.skipWaiting())
  );
});

// Activate Event - Clean old caches
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          if (cacheName !== CACHE_NAME) {
            return caches.delete(cacheName);
          }
        })
      );
    }).then(() => self.clients.claim())
  );
});

// Fetch Event - Serve from Cache, Fallback to Network
self.addEventListener('fetch', (event) => {
  event.respondWith(
    caches.match(event.request)
      .then((response) => {
        // Return cache hit if found
        if (response) {
          return response;
        }
        // Clone request for fetch
        const fetchRequest = event.request.clone();

        return fetch(fetchRequest).then(
          (response) => {
            // Check if valid response
            if(!response || response.status !== 200 || response.type !== 'basic') {
              return response;
            }

            // Don't cache API calls or external resources not in allowlist heavily
            // For this simple PWA, we largely rely on the install cache for the shell
            return response;
          }
        ).catch(() => {
            // Fallback for navigation requests if offline
            if (event.request.mode === 'navigate') {
                return caches.match('./index.html');
            }
        });
      })
  );
});

import { GoogleGenerativeAI, HarmCategory, HarmBlockThreshold } from "@google/generative-ai";
import { MedicineData, PatientProfile, ChatMessage, DermaData, ScanHistoryItem, DietPlan } from "../types.ts";

// Robustly retrieve API Key
const getApiKey = (): string => {
  if (typeof process !== "undefined" && process.env?.API_KEY) {
    return process.env.API_KEY;
  }
  if (typeof window !== "undefined" && (window as any).process?.env?.API_KEY) {
    return (window as any).process.env.API_KEY;
  }
  return "";
};

const apiKey = getApiKey();
const genAI = new GoogleGenerativeAI(apiKey);

// SAFETY SETTINGS: Crucial for Medical Apps
const SAFETY_SETTINGS = [
  { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_NONE },
  { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_NONE },
  { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_NONE },
  { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_NONE },
];

// Helper to clean JSON string (remove markdown fences if present)
const cleanJsonString = (str: string): string => {
    if (!str) return "{}";
    let cleaned = str.trim();
    if (cleaned.startsWith("```json")) {
        cleaned = cleaned.replace(/^```json\s*/, "").replace(/\s*```$/, "");
    } else if (cleaned.startsWith("```")) {
        cleaned = cleaned.replace(/^```\s*/, "").replace(/\s*```$/, "");
    }
    return cleaned;
};

// Error Helper
const getFriendlyErrorMessage = (error: any): string => {
    const msg = error.message || JSON.stringify(error) || "";
    if (msg.includes("429") || msg.includes("RESOURCE_EXHAUSTED")) return "Daily Scan Limit Reached. Please try again tomorrow.";
    if (msg.includes("500") || msg.includes("overloaded")) return "AI Service Busy. Please try again in a moment.";
    if (msg.includes("404") || msg.includes("NOT_FOUND")) return "AI Model unavailable. Retrying with backup...";
    if (msg.includes("API key not valid")) return "Invalid API Key. Please check settings.";
    if (msg.includes("invalid format")) return "Analysis failed. Please try a clearer image.";
    if (msg.includes("offline") || msg.includes("internet")) return "No Internet Connection. Please check your network.";
    return "Scan failed. Please ensure image is clear and try again.";
};

