export const getDoctorAIResponse = async (history: ChatMessage[], scanHistory?: ScanHistoryItem[]): Promise<string> => {
  try {
    // For Chat, we usually use getGenerativeModel directly to startChat, 
    // but to keep fallback logic simple, we will format it as a single multi-turn prompt or use 'generateContent' with history text.
    // Using generateContent with strict prompt is often more stable for 1.5-flash fallback.

    let contextData = "";
    if (scanHistory && scanHistory.length > 0) {
        const recentMedNames = scanHistory.slice(0, 5).map(item => item.medicineName).join(', ');
        contextData = `User's recent scans: [${recentMedNames}]. Use this for context.`;
    }

    // Convert history to text format for simple prompt (more robust fallback than ChatSession object across models)
    const conversation = history.map(msg => `${msg.role === 'user' ? 'User' : 'Doctor'}: ${msg.content}`).join('\n');

    const prompt = `
    You are MediIQ Doctor AI, a professional medical assistant.
    ${contextData}
    Current Conversation:
    ${conversation}

    User's last message is at the end. Reply as Doctor. Keep it helpful, concise, and safe.
    ALWAYS include a disclaimer that you are an AI.
    `;

    const responseText = await generateContentWithFallback({ contents: prompt }, false);
    return responseText;
  } catch (error: any) {
    console.error("Doctor AI Error:", error);
    if (error.message?.includes("offline")) return "I cannot check online resources right now. Please connect to the internet.";
    if (error.message?.includes("429")) return "I am busy right now. Please try again later.";
    return "I cannot answer right now due to a connection issue.";
  }
};

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App.tsx';

console.log("App Loader: Starting initialisation...");

const mountApp = () => {
  try {
    const rootElement = document.getElementById('root');
    if (!rootElement) {
      console.error("App Loader: FATAL - Could not find root element '#root'");
      return;
    }

    // Clear the static loader
    // rootElement.innerHTML = ''; 
    // React 18 createRoot handles clearing, but we ensure element is ready.

    console.log("App Loader: Root element found. Creating React root...");
    const root = ReactDOM.createRoot(rootElement);

    console.log("App Loader: Rendering App component...");
    root.render(
      <React.StrictMode>
        <App />
      </React.StrictMode>
    );
    console.log("App Loader: Render signal sent successfully.");
  } catch (error) {
    console.error("App Loader: CRITICAL ERROR during render:", error);
    // index.html global error handler will catch this, but just in case:
    const rootElement = document.getElementById('root');
    if (rootElement) {
      rootElement.innerHTML = `
        <div style="padding: 20px; color: #e11d48; text-align: center; font-family: sans-serif; display: flex; flex-direction: column; justify-content: center; height: 100vh;">
          <h1 style="font-size: 24px; font-weight: bold;">Launch Failed</h1>
          <p style="margin-top: 10px;">React failed to mount.</p>
          <pre style="text-align: left; background: #f1f5f9; padding: 15px; border-radius: 8px; font-size: 12px; margin-top: 20px; overflow: auto;">${error instanceof Error ? error.message : String(error)}</pre>
          <button onclick="window.location.reload()" style="margin-top: 20px; background: #0d9488; color: white; padding: 10px 20px; border-radius: 8px; border: none; font-weight: bold; cursor: pointer;">Retry</button>
        </div>
      `;
    }
  }
};

// Start the mount process
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', mountApp);
} else {
  mountApp();
}

const CACHE_NAME = 'mediiq-offline-v2';
const ASSETS_TO_CACHE = [
  './',
  './index.html',
  // We can't pre-cache all CDN links easily without a build step, 
  // so we rely on runtime caching in the fetch handler.
];

// Install Event
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => cache.addAll(ASSETS_TO_CACHE))
      .then(() => self.skipWaiting())
  );
});

// Activate Event
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          if (cacheName !== CACHE_NAME) {
            return caches.delete(cacheName);
          }
        })
      );
    }).then(() => self.clients.claim())
  );
});

// Fetch Event
self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);

  // Strategy: Stale-While-Revalidate for critical CDNs
  if (url.hostname === 'esm.sh' || url.hostname === 'cdn.tailwindcss.com' || url.hostname === 'fonts.googleapis.com' || url.hostname === 'fonts.gstatic.com') {
    event.respondWith(
      caches.open(CACHE_NAME).then((cache) => {
        return cache.match(event.request).then((cachedResponse) => {
          const fetchPromise = fetch(event.request).then((networkResponse) => {
            if (networkResponse.status === 200) {
              cache.put(event.request, networkResponse.clone());
            }
            return networkResponse;
          }).catch(() => {
             // Swallow network errors if we have a cache, otherwise return undefined
             return cachedResponse; 
          });
          return cachedResponse || fetchPromise;
        });
      })
    );
    return;
  }

  // Strategy: Network First, Fallback to Cache for everything else (like API calls - generally won't work offline but safer default)
  // Actually for App Shell (index.html), we want Cache First for speed/offline.

  if (event.request.mode === 'navigate') {
    event.respondWith(
      caches.match('./index.html').then((response) => {
        return response || fetch(event.request);
      }).catch(() => {
        return caches.match('./index.html');
      })
    );
    return;
  }

  event.respondWith(
    caches.match(event.request).then((response) => {
      return response || fetch(event.request);
    })
  );
});

import React, { useRef, useState, useCallback } from 'react';
import { analyzeMedicineImage } from '../services/geminiService';
import { MedicineData, PatientProfile, AgeGroup, Gender, Language, FamilyMember } from '../types';

interface ScannerProps {
  familyMembers: FamilyMember[];
  onScanComplete: (data: MedicineData, profile: PatientProfile) => void;
  onError: (msg: string) => void;
}

const Scanner: React.FC<ScannerProps> = ({ familyMembers, onScanComplete, onError }) => {
  const [images, setImages] = useState<string[]>([]);
  const [analyzing, setAnalyzing] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [showOfflineModal, setShowOfflineModal] = useState(false);

  const [ageGroup, setAgeGroup] = useState<AgeGroup>('adult');
  const [gender, setGender] = useState<Gender>('male');
  const [isPregnant, setIsPregnant] = useState(false);
  const [isBreastfeeding, setIsBreastfeeding] = useState(false);
  const [language, setLanguage] = useState<Language>('english');

  const cameraInputRef = useRef<HTMLInputElement>(null);
  const galleryInputRef = useRef<HTMLInputElement>(null);

  const checkOnline = () => {
      if (!navigator.onLine) {
          setShowOfflineModal(true);
          return false;
      }
      return true;
  };

  const triggerCamera = () => {
      if (checkOnline()) cameraInputRef.current?.click();
  };

  const triggerGallery = () => {
      if (checkOnline()) galleryInputRef.current?.click();
  };

  const handleFileChange = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    const file = files[0];
    const reader = new FileReader();
    reader.onloadend = () => { 
        setImages(prev => [...prev, reader.result as string].slice(-3)); 
    };
    reader.readAsDataURL(file);
    if (e.target) e.target.value = ''; 
  }, []);

  const removeImage = (index: number) => {
      setImages(prev => prev.filter((_, i) => i !== index));
  };

  const startAnalysis = async (selectedProfile?: PatientProfile) => {
    if (!checkOnline()) return;
    if (images.length === 0) return;

    setShowForm(false);
    setAnalyzing(true);
    try {
      const profile = selectedProfile || { ageGroup, gender, isPregnant, isBreastfeeding, language };
      const data = await analyzeMedicineImage(images, profile);
      onScanComplete(data, profile);
    } catch (err: any) {
      onError(err.message || "Scan failed. Ensure the text is clear and try again.");
    } finally {
      setAnalyzing(false);
    }
  };

  if (showForm) {
      return (
          <div className="w-full max-w-md mx-auto bg-white rounded-[3.5rem] shadow-[0_25px_60px_-15px_rgba(0,0,0,0.15)] overflow-hidden animate-slide-up relative z-[110] border border-slate-50 mb-20">
              {/* Clinical Header */}
              <div className="bg-slate-50 p-8 pb-6 border-b border-slate-100">
                  <div className="flex justify-between items-center mb-4">
                      <div className="flex items-center space-x-3">
