  } catch (e) {
    return "Please ask your doctor.";
  }
};

export const getHealthTip = async (): Promise<string> => {
    try {
        const responseText = await generateContentWithFallback({
            contents: { parts: [{ text: "One short health tip about medicine safety (15 words max)." }] }
        }, false);
        return responseText;
    } catch (e) {
        return "Stay hydrated and check expiry dates.";
    }
}

export const getDoctorAIResponse = async (history: ChatMessage[], scanHistory?: ScanHistoryItem[]): Promise<string> => {
  try {
    let contextData = "";
    if (scanHistory && scanHistory.length > 0) {
        const recentMedNames = scanHistory.slice(0, 5).map(item => item.medicineName).join(', ');
        contextData = `User's recent scans: [${recentMedNames}]. Use this for context.`;
    }

    const conversation = history.map(msg => `${msg.role === 'user' ? 'User' : 'Doctor'}: ${msg.content}`).join('\n');

    const prompt = `
    You are MediIQ Doctor AI, a professional medical assistant.
    ${contextData}
    Current Conversation:
    ${conversation}

    User's last message is at the end. Reply as Doctor. Keep it helpful, concise, and safe.
    ALWAYS include a disclaimer that you are an AI.
    `;

    const responseText = await generateContentWithFallback({ contents: { parts: [{ text: prompt }] } }, false);
    return responseText;
  } catch (error: any) {
    console.error("Doctor AI Error:", error);
    if (error.message?.includes("offline")) return "I cannot check online resources right now. Please connect to the internet.";
    if (error.message?.includes("429")) return "I am busy right now. Please try again later (Quota Exceeded).";
    return "I cannot answer right now due to a connection issue.";
  }
};

import React, { useRef, useState, useCallback } from 'react';
import { analyzeMedicineImage } from '../services/geminiService';
import { MedicineData, PatientProfile, AgeGroup, Gender, Language, FamilyMember } from '../types';

interface ScannerProps {
  familyMembers: FamilyMember[];
  onScanComplete: (data: MedicineData, profile: PatientProfile) => void;
  onError: (msg: string) => void;
}

const Scanner: React.FC<ScannerProps> = ({ familyMembers, onScanComplete, onError }) => {
  const [images, setImages] = useState<string[]>([]);
  const [analyzing, setAnalyzing] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [showOfflineModal, setShowOfflineModal] = useState(false);

  // New Error State for better feedback
  const [scanError, setScanError] = useState<string | null>(null);

  const [ageGroup, setAgeGroup] = useState<AgeGroup>('adult');
  const [gender, setGender] = useState<Gender>('male');
  const [isPregnant, setIsPregnant] = useState(false);
  const [isBreastfeeding, setIsBreastfeeding] = useState(false);
  const [language, setLanguage] = useState<Language>('english');

  const cameraInputRef = useRef<HTMLInputElement>(null);
  const galleryInputRef = useRef<HTMLInputElement>(null);

  const checkOnline = () => {
      if (!navigator.onLine) {
          setShowOfflineModal(true);
          return false;
      }
      return true;
  };

  const triggerCamera = () => {
      setScanError(null);
      if (checkOnline()) cameraInputRef.current?.click();
  };

  const triggerGallery = () => {
      setScanError(null);
      if (checkOnline()) galleryInputRef.current?.click();
  };

  const handleFileChange = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    const file = files[0];
    const reader = new FileReader();
    reader.onloadend = () => { 
        setImages(prev => [...prev, reader.result as string].slice(-3)); 
    };
    reader.readAsDataURL(file);
    if (e.target) e.target.value = ''; 
  }, []);

  const removeImage = (index: number) => {
      setImages(prev => prev.filter((_, i) => i !== index));
  };

  const startAnalysis = async (selectedProfile?: PatientProfile) => {
    if (!checkOnline()) return;
    if (images.length === 0) return;

    setShowForm(false);
    setScanError(null);
    setAnalyzing(true);
    try {
      const profile = selectedProfile || { ageGroup, gender, isPregnant, isBreastfeeding, language };
      const data = await analyzeMedicineImage(images, profile);
      onScanComplete(data, profile);
      setImages([]); // Clear images on success
    } catch (err: any) {
      // Set local error state for UI display
      setScanError(err.message || "Scan failed. Ensure the text is clear and try again.");
      console.error("Scan Process Failed:", err);
    } finally {
      setAnalyzing(false);
    }
  };

  if (showForm) {
      return (
          <div className="w-full max-w-md mx-auto bg-white rounded-[3.5rem] shadow-[0_25px_60px_-15px_rgba(0,0,0,0.15)] overflow-hidden animate-slide-up relative z-[110] border border-slate-50 mb-20">
